"const express = require('express');
const cors = require('cors');
const path = require('path');
const { initDb } = require('./db/database');

const { router: authRouter } = require('./routes/auth');
const dashboardRouter = require('./routes/dashboard');
const curriculumRouter = require('./routes/curriculum');
const trainingsRouter = require('./routes/trainings');
const participantsRouter = require('./routes/participants');
const rankingRouter = require('./routes/ranking');
const publicRouter = require('./routes/public');
const systemRouter = require('./routes/system');

const app = express();
const PORT = process.env.PORT || 5000;

// Initialize Database & Seed data
initDb();

app.use(cors());
app.use(express.json({ limit: '50mb' }));
app.use(express.urlencoded({ extended: true, limit: '50mb' }));

// API Routes
app.use('/api/auth', authRouter);
app.use('/api/dashboard', dashboardRouter);
app.use('/api', curriculumRouter);
app.use('/api', trainingsRouter);
app.use('/api/participants', participantsRouter);
app.use('/api/rankings', rankingRouter);
app.use('/api/public', publicRouter);
app.use('/api/system', systemRouter);

// Serve static frontend build if it exists
const clientDist = path.join(__dirname, '..', 'client', 'dist');
app.use(express.static(clientDist));
app.get('*', (req, res, next) => {
  if (req.path.startsWith('/api')) {
    return next();
  }
  const indexHtml = path.join(clientDist, 'index.html');
  res.sendFile(indexHtml, (err) => {
    if (err) {
      res.status(200).send('Training Agency API Server is running. Client build will be served here.');
    }
  });
});

app.listen(PORT, () => {
  console.log(`====================================================`);
  console.log(` TRAINING AGENCY Local Server is running!`);
  console.log(` URL: http://localhost:${PORT}`);
  console.log(` Mode: Offline / Local SQLite MVP`);
  console.log(`====================================================`);
});

module.exports = app;
"

